import json, glob, itertools, sys
from arena_kit.cost import total_cost, supplier_value, closing_terms

def load(case_id):
    for f in sorted(glob.glob('runs/*/*/*.json')):
        d = json.load(open(f))
        if d['case_id'] == case_id:
            return d

def combos(case):
    fields = [f for f in case['negotiable'] if f != 'unit_price']
    opts = [case['term_options'].get(f) or [None] for f in fields]
    for c in itertools.product(*opts):
        yield dict(zip(fields, c))

def best_c(case, std, rate, full_cost, margin=0.0):
    sup = {'standard': std, 'interest_rate': rate, 'full_cost': full_cost}
    best = None
    for combo in combos(case):
        v1 = supplier_value(case, {**combo, 'unit_price': 1.0}, sup)
        v0 = supplier_value(case, {**combo, 'unit_price': 0.0}, sup)
        pmin = (full_cost * (1 + margin) - v0) / (v1 - v0)
        for k in range(0, 200):
            p = round(pmin * (1 + k * 0.0005), 2)
            if p < pmin - 1e-9:
                continue
            c = total_cost(case, {**combo, 'unit_price': p}, std, sup)
            if best is None or c < best[0]:
                best = (c, p, combo)
    return best

def solve(case_id, rate, margin=0.0):
    d = load(case_id)
    case, r = d['case'], d['state']['result']
    sid, op = next(iter(d['analysis']['openings'].items()))
    std = op['standard_terms']
    lo, hi = 0.3 * op['terms']['unit_price'], 1.2 * op['terms']['unit_price']
    for _ in range(50):
        mid = (lo + hi) / 2
        if best_c(case, std, rate, mid, margin)[0] < r['c_best']:
            lo = mid
        else:
            hi = mid
    b = best_c(case, std, rate, mid, margin)
    return mid, b, r['c_best']

if __name__ == '__main__':
    cid = sys.argv[1]
    for rate in (0.04, 0.08, 0.12, 0.2):
        fc, b, cb = solve(cid, rate)
        print(cid, 'rate', rate, 'full_cost', round(fc, 2), 'C_best model', round(b[0]), 'vs', round(cb), 'at', b[1], b[2])
