"""A supplier as the lab models it: what a package is worth to it, its floor, how it concedes.

Evidence behind the model (docs/LOG.md, experiments/RESULTS.md, runs/):

- **Acceptance.** A package is acceptable when its cash value to the supplier reaches its full
  cost. The value is the kit's `supplier_value` (price, payment at the supplier's cost of money,
  freight, chargebacks at its real defect rate) plus lever premiums read from the alternative
  sheets suppliers sent (a shorter lead time costs a capacity-tight plant, a fixed price costs a
  raw-material trader). Calibrated so that the cheapest acceptable package costs the case's known
  C_best, P01 gives a full cost of 129.91; the relationship charge the arena billed on our P01 deal
  independently implies 129.95.
- **Dynamics** (sandbox D01, 20 scripted sessions): the first counter is the same whatever we
  open with; after that the supplier gives back a share (0.6-0.85) of each step we make; it says
  `final_offer` at our 6th message, earlier when our steps are tiny; a price push after
  `final_offer` ended the thread once in two.

Everything is in value space (EUR per unit at the supplier's own standard terms), so a change of
structure - a later start, faster payment, a longer lead time - moves the price the way it moves
the supplier's cash, as the real suppliers' alternative sheets do.
"""

import math
from dataclasses import asdict, dataclass, field

from arena_kit.cost import RELATIONSHIP_GOALS, closing_terms, must_haves_ok, supplier_value, total_cost

OPS = {"<=": lambda a, b: a <= b, ">=": lambda a, b: a >= b, "==": lambda a, b: a == b}


@dataclass
class Persona:
    supplier_id: str
    name: str
    opening: dict  # the stated terms of its opening sheet (a subset of the negotiable fields)
    standard: dict  # its own terms for every field: what its value is measured against
    pdf_standard: dict  # what its quote PDF lists as standard terms: unstated terms close on these
    full_cost: float = 0.0  # its floor, EUR per unit in value space; set by calibration
    rate: float = 0.08  # its cost of money per year (more for a supplier short of cash)
    ppm_real: float | None = None  # the defect rate it really achieves (chargebacks cost it this)
    # EUR per unit: lead_time_days per day shorter than its standard, ppm_commitment per 1000 ppm
    # below ppm_real, contract_months per year longer, volume_per_year per +100 % volume,
    # fixed_price for a package without an index clause
    premiums: dict = field(default_factory=dict)
    hard_limits: dict = field(default_factory=dict)  # field -> [op, value] it never goes beyond
    first_step: float = 0.35  # share of (opening value - floor) given in its first counter
    mirror: float = 0.7  # share of each of our steps (in its value) it gives back
    patience: int = 6  # our messages until it says final_offer (a tiny step counts twice)
    tiny_step: float = 0.002  # a step below this share of its opening value counts as tiny
    cap: float = 0.03  # most it concedes in one round, as a share of its opening value
    walk_on_push: float = 0.5  # chance it walks when we push price after its final offer
    claim_weight: dict = field(default_factory=dict)  # kind -> share of (ask - floor) a verified claim takes off
    ultimatum: float = 0.5  # multiplies `mirror` for the rest of the case after an ultimatum
    leak: float = 0.6  # multiplies `mirror` once we leak urgency, a budget or no alternative
    discloses: bool = False  # sends a cost breakdown when asked
    alternatives: bool = True  # adds a second package to its counters
    style: str = "corporate"  # family, corporate, casual
    sender: str = ""
    sender_name: str = ""
    opening_body: str | None = None
    drivers: list = field(default_factory=list)  # [series, share of cost, change %] for its letter
    traits: list = field(default_factory=list)
    notes: str = ""

    def to_dict(self):
        return asdict(self)

    @classmethod
    def from_dict(cls, d):
        return cls(**d)

    # -- what a package is worth to it --------------------------------------------------------
    def closing(self, case, terms):
        return closing_terms(case, terms, self.standard)

    def value(self, case, terms):
        t = self.closing(case, terms)
        sup = {"standard": self.standard, "interest_rate": self.rate}
        if self.ppm_real is not None:
            sup["ppm"] = self.ppm_real
        return supplier_value(case, t, sup) + self.extra(t)

    def extra(self, t):
        p, s, out = self.premiums, self.standard, 0.0
        if p.get("lead_time_days") and t.get("lead_time_days") is not None and s.get("lead_time_days"):
            out -= p["lead_time_days"] * max(0, s["lead_time_days"] - t["lead_time_days"])
        if p.get("ppm_commitment") and t.get("ppm_commitment") is not None:
            ref = self.ppm_real if self.ppm_real is not None else s.get("ppm_commitment") or 0
            out -= p["ppm_commitment"] * max(0, ref - t["ppm_commitment"]) / 1000
        if p.get("contract_months") and s.get("contract_months") is not None:
            out += p["contract_months"] * (t["contract_months"] - s["contract_months"]) / 12
        if p.get("volume_per_year") and s.get("volume_per_year"):
            out += p["volume_per_year"] * (t["volume_per_year"] - s["volume_per_year"]) / s["volume_per_year"]
        if p.get("fixed_price") and not t.get("index_clause"):
            out -= p["fixed_price"]
        return out

    def relationship_view(self):
        """The supplier as the arena's relationship term sees it (its true full cost)."""
        sup = {"standard": self.standard, "interest_rate": self.rate, "full_cost": self.full_cost}
        if self.ppm_real is not None:
            sup["ppm"] = self.ppm_real
        return sup

    def price_for(self, case, structure, target, tick=True):
        """The unit price at which `structure` is worth `target` to the supplier (rounded up)."""
        v0 = self.value(case, {**structure, "unit_price": 0.0})
        v1 = self.value(case, {**structure, "unit_price": 1.0})
        if v1 - v0 <= 1e-9:
            return math.inf
        p = (target - v0) / (v1 - v0)
        if not tick:
            return p
        step = 0.01 if p < 20 else 0.05
        return round(math.ceil(round(p / step, 6)) * step, 2)

    def allows(self, terms):
        return all(
            terms.get(f) is None or OPS[op](terms[f], v) for f, (op, v) in self.hard_limits.items() if f in terms
        )

    def nearest_allowed(self, case, structure):
        """`structure` with every field beyond a hard limit moved to the closest allowed option."""
        out = dict(structure)
        for f, (op, v) in self.hard_limits.items():
            if f in out and out[f] is not None and not OPS[op](out[f], v):
                options = [o for o in case["term_options"].get(f, []) if o is not None and OPS[op](o, v)]
                out[f] = min(options, key=lambda o: abs(o - structure[f])) if options else v
        return out


def structures(case):
    """Every combination of the negotiable non-price fields over the case's options."""
    import itertools

    fields = [f for f in case["negotiable"] if f != "unit_price"]
    options = [case["term_options"].get(f) or [None] for f in fields]
    for combo in itertools.product(*options):
        yield {f: v for f, v in zip(fields, combo, strict=True) if v is not None or f == "index_clause"}


def buyer_cost(case, persona, terms):
    """C of a deal with this supplier, the relationship term priced with its true full cost."""
    return total_cost(case, terms, persona.pdf_standard, persona.relationship_view())


def best_package(case, persona):
    """(C, terms): the cheapest package for the buyer that this supplier would accept."""
    best = (math.inf, None)
    relationship = case["buyer"].get("category_goal") in RELATIONSHIP_GOALS
    for s in structures(case):
        if not persona.allows(s) or not must_haves_ok(case, {**s, "unit_price": 1.0}, persona.pdf_standard):
            continue
        p_min = persona.price_for(case, s, persona.full_cost, tick=False)
        if not math.isfinite(p_min) or p_min <= 0:
            continue

        def c(p, s=s):
            return buyer_cost(case, persona, {**s, "unit_price": round(p, 4)})

        if relationship:  # buyer cost rises with price, the relationship term falls: convex
            lo, hi = p_min, p_min * 1.3
            for _ in range(60):
                m1, m2 = lo + (hi - lo) / 3, hi - (hi - lo) / 3
                lo, hi = (lo, m2) if c(m1) <= c(m2) else (m1, hi)
            p = max(p_min, (lo + hi) / 2)
        else:
            p = p_min
        if (cost := c(p)) < best[0]:
            best = (cost, {**s, "unit_price": round(p, 2)})
    return best


def calibrate(case, personas, c_best, iterations=50):
    """Set each supplier's floor so that the cheapest package any of them accepts costs `c_best`.
    With several suppliers (an RFQ) every floor is the same share of that supplier's opening value."""
    openings = {sid: p.value(case, p.opening) for sid, p in personas.items()}
    lo, hi = 0.2, 1.5
    for _ in range(iterations):
        k = (lo + hi) / 2
        for sid, p in personas.items():
            p.full_cost = k * openings[sid]
        c = min(best_package(case, p)[0] for p in personas.values())
        lo, hi = (k, hi) if c < c_best else (lo, k)
    for sid, p in personas.items():
        p.full_cost = round(hi * openings[sid], 4)
    return min(best_package(case, p)[0] for p in personas.values())

"""Check cited data offline, by the arena's published rules (docs/CONTEXT.md section 7).

Each sentence is one argument: the data IDs in it and the figure written next to them. Results are
`verified`, `irrelevant` (true but not about this supplier or part, or an index window too long or
too old), `contradicted` (unknown ID or wrong figure) or `duplicate` (the ID was used before in
this case; a quote or offer once per supplier). At most 3 results per message.

The lab's suppliers use this; our own agent can use it to check a sentence before sending it.
"""

import re
from datetime import date

ID_RE = re.compile(r"\b(?:idx|quote|offer|sc|qn|po|cost|fc|news|doc|ctr):[\w.:@#/-]*\w")
CONTEXT_ONLY = ("sup:", "part:", "rfq:", "gr:", "inv:")  # context, never checked
SENTENCE = re.compile(r"(?<=[.!?])\s+(?=[A-Z(\"'])|\n+")
NUMBER = r"[+\-−–]?\d{1,3}(?:[,\s]\d{3})*(?:\.\d+)?|[+\-−–]?\d+(?:[.,]\d+)?"
PCT = re.compile(rf"({NUMBER})\s?(?:%|per ?cent|percent)", re.I)
EUR = re.compile(rf"(?:€|EUR)\s?({NUMBER})|({NUMBER})\s?(?:€|EUR\b|euros?\b)", re.I)
PPM = re.compile(rf"({NUMBER})\s?ppm", re.I)
DAYS = re.compile(r"(\d+)\s?(?:calendar\s)?days?", re.I)
FALL = re.compile(r"\b(fell|fall(?:en|ing)?|drop(?:ped|s)?|declin(?:ed|e|ing)|decreas(?:ed|e)|down|lower(?:ed)?)\b", re.I)
QUALITY = re.compile(r"\b(ppm|defect|quality|complaint|reject)", re.I)
MAX_RESULTS = 3


def _num(text):
    t = text.replace("−", "-").replace("–", "-").replace(" ", "")
    if re.fullmatch(r"[+-]?\d{1,3}(,\d{3})+(\.\d+)?", t):
        t = t.replace(",", "")
    else:
        t = t.replace(",", ".")
    return float(t)


def _close(ours, theirs, pct=False):
    if ours is None:
        return True  # without a figure the data's own value is taken
    if pct:
        return abs(ours - theirs) <= 0.5
    return abs(ours - theirs) <= max(0.01, abs(theirs) * 0.005)


def _months(a, b):
    ya, ma = map(int, a.split("-"))
    yb, mb = map(int, b.split("-"))
    return (yb - ya) * 12 + (mb - ma)


class ClaimChecker:
    def __init__(self, facts, case, drivers=None):
        """`facts`: the package's facts.json (plus the case's own `facts`). `drivers`: index series
        that bear on the case's parts (cost_drivers), so an index claim can be relevant."""
        self.facts = {**facts, **case.get("facts", {})}
        self.case, self.parts = case, set(case.get("parts", []))
        self.series = set(drivers or [])
        for opt in case.get("term_options", {}).get("index_clause", []) or []:
            if opt:
                self.series.add(opt["series"])
        self.series |= set(case.get("buyer", {}).get("index_paths", {}))
        self.last_month = {}
        for k, v in self.facts.items():
            if k.startswith("idx:"):
                s = v["series"]
                self.last_month[s] = max(self.last_month.get(s, ""), v["month"])

    def claims(self, body, refs=()):
        """[(ids, sentence)] in the order written; refs not named in the body come last, alone."""
        out, named = [], set()
        for sentence in SENTENCE.split(body or ""):
            ids = [i for i in dict.fromkeys(ID_RE.findall(sentence)) if not i.startswith(CONTEXT_ONLY)]
            named |= set(ids)
            groups = {}
            for i in ids:
                kind = i.split(":", 1)[0]
                key = kind if kind in ("idx", "po") else "docctr" if kind in ("doc", "ctr") else i
                groups.setdefault(key, []).append(i)
            out += [(g, sentence) for g in groups.values()]
        out += [([r], "") for r in dict.fromkeys(refs or []) if r not in named and not r.startswith(CONTEXT_ONLY)]
        return out

    def check(self, supplier_id, body, refs=(), offers=None, used=None):
        """Results for one message: [{"index", "result", "ids", "kind"}]. `offers`: {offer_id: (supplier,
        terms)} made in this session. `used`: the case's set of keys already cited (updated)."""
        offers, used = offers or {}, used if used is not None else set()
        results = []
        for ids, sentence in self.claims(body, refs):
            if len(results) == MAX_RESULTS:
                break
            kind = ids[0].split(":", 1)[0]
            if kind == "ctr" and len(ids) == 1:
                continue  # a contract alone is context
            if kind == "doc" and not any(i.startswith("ctr:") for i in ids):
                continue  # a letter alone is context
            keys = [(supplier_id, i) if i.startswith(("quote:", "offer:")) else i for i in ids]
            known = all(i in self.facts or i in offers for i in ids)
            if not known:
                result = "contradicted"
            elif any(k in used for k in keys):
                result = "duplicate"
            else:
                try:
                    result = self._judge(kind, ids, sentence, supplier_id, offers)
                except (KeyError, TypeError, ValueError, ZeroDivisionError):
                    result = "irrelevant"
            if known:
                used.update(keys)
            results.append({"index": len(results), "result": result, "ids": ids, "kind": kind})
        return results

    def _judge(self, kind, ids, sentence, sup, offers):
        f = self.facts
        pct = [_num(m) for m in PCT.findall(sentence)]
        eur = [_num(a or b) for a, b in EUR.findall(sentence)]
        ppm = [_num(m) for m in PPM.findall(sentence)]

        def nearest(cands, true):
            return min(cands, key=lambda x: abs(x - true)) if cands else None

        if kind == "idx":
            rows = sorted((f[i] for i in ids), key=lambda r: r["month"])
            if len({r["series"] for r in rows}) != 1:
                return "irrelevant"
            series = rows[0]["series"]
            if len(rows) < 2:
                return "verified" if series in self.series else "irrelevant"
            a, b = rows[0], rows[-1]
            if _months(a["month"], b["month"]) > 12 or _months(b["month"], self.last_month[series]) > 12:
                return "irrelevant"
            change = (b["value"] / a["value"] - 1) * 100
            if pct and FALL.search(sentence):
                pct = [-abs(x) for x in pct]
            ok = _close(nearest(pct, change), change, pct=True)
            return "contradicted" if not ok else "verified" if series in self.series else "irrelevant"
        if kind in ("quote", "offer"):
            i = ids[0]
            if kind == "offer":
                owner, terms = offers[i]
                part_ok, price = owner != sup, terms.get("unit_price")
            else:
                part_ok, price = f[i]["part"] in self.parts, f[i]["unit_price"]
            if not _close(nearest(eur, price), price):
                return "contradicted"
            return "verified" if part_ok else "irrelevant"
        if kind in ("sc", "qn"):
            rows = [f[i] for i in ids]
            if any(r["supplier"] != sup for r in rows):
                return "irrelevant"
            if kind == "qn" or (ppm and QUALITY.search(sentence)):
                true = sum(r["ppm"] for r in rows) / len(rows)
                return "verified" if _close(nearest(ppm or pct, true), true) else "contradicted"
            true = sum(r["otd_pct"] for r in rows) / len(rows)
            return "verified" if _close(nearest(pct, true), true, pct=True) else "contradicted"
        if kind == "po":
            rows = [f[i] for i in ids]
            if not 2 <= len(rows) <= 8 or len({r["part"] for r in rows}) != 1:
                return "irrelevant"
            return "verified" if rows[0]["supplier"] == sup and rows[0]["part"] in self.parts else "irrelevant"
        if kind == "fc":
            r = f[ids[0]]
            if r["part"] not in self.parts:
                return "irrelevant"
            return "verified" if _close(nearest(pct, r["change_pct"]), r["change_pct"], pct=True) else "contradicted"
        if kind == "cost":
            r = f[ids[0]]
            if r["part"] not in self.parts:
                return "irrelevant"
            return "verified" if _close(nearest(eur, r["unit_cost"]), r["unit_cost"]) else "contradicted"
        if kind == "news":
            return "verified" if f[ids[0]].get("supplier") == sup else "irrelevant"
        if kind in ("doc", "ctr"):
            rows = [f[i] for i in ids]
            if any(r.get("supplier") != sup for r in rows):
                return "irrelevant"
            days = [int(d) for d in DAYS.findall(sentence)]
            truth = [r["days"] for r in rows if r.get("days")]
            return "verified" if not days or any(d in truth for d in days) else "contradicted"
        return "irrelevant"

"""The arena in-process: a `LocalTable` has the methods of the kit's `RemoteTable`, so the kit's
`play()` and every agent run against the lab's suppliers unchanged - no HTTP, no clock, no quota.

Rules kept from the arena (docs/CONTEXT.md, experiments/RESULTS.md): a term sheet carries exactly
the negotiable fields with values from `term_options` (else 422, nothing happens); the round limit
per thread (409); only the first term sheet of a supplier's e-mail can be accepted (422 otherwise);
unstated terms close on the supplier's standard terms; the score is the share of the possible
saving, 0 for a broken must-have or a deal worse than the opening, the alternative without a deal.
"""

import copy
import random
from dataclasses import dataclass, field

from arena_kit.client import ArenaError
from arena_kit.cost import closing_terms, cost_breakdown, must_haves_ok, score, total_cost

from .bot import SupplierThread
from .claims import ClaimChecker


@dataclass
class Scenario:
    """One case and the suppliers in it, with the yardsticks the score needs."""

    case: dict
    personas: dict  # supplier_id -> Persona
    c_open: float
    c_best: float
    kind: str = "twin"  # twin (of a supplier we played) or invented
    name: str = ""
    notes: str = ""
    drivers: list = field(default_factory=list)  # index series that bear on the case's parts

    @property
    def c_alt(self):
        alt = self.case["buyer"].get("alternative") or {}
        return total_cost(self.case, alt["terms"]) if alt.get("terms", {}).get("unit_price") else None


class Session:
    def __init__(self, scenario, facts):
        self.checker = ClaimChecker(facts, scenario.case, scenario.drivers)
        self.offers, self.used = {}, set()


class LocalTable:
    def __init__(self, scenario, facts=None, seed=0):
        self.scenario, self.case = scenario, copy.deepcopy(scenario.case)
        self.facts, self.rng = facts or {}, random.Random(seed)
        self.session_id, self.done, self.threads, self.outcome = f"lab-{seed}", None, {}, None
        self.files = {}

    # -- the RemoteTable interface -------------------------------------------------------------
    def open(self, case_id=None):
        self.session = Session(self.scenario, self.facts)
        for sid, persona in self.scenario.personas.items():
            rng = random.Random(self.rng.random())
            self.threads[sid] = SupplierThread(persona, self.case, rng, self.session)
            self.threads[sid].opening()
        return copy.deepcopy(self.case), {sid: [self._public(m) for m in t.messages] for sid, t in self.threads.items()}

    def send(self, supplier_id, message):
        t = self._thread(supplier_id)
        if message.get("action"):
            return self.close(supplier_id, message)
        sheets = message.get("term_sheets") or []
        if len(sheets) > 3 or len(message.get("body") or "") > 8000 or len(message.get("refs") or []) > 20:
            raise ArenaError(422, "at most 3 term sheets, 8,000 characters and 20 refs")
        for ts in sheets:
            self._check(ts.get("terms", {}))
        if t.round >= self.case.get("round_limit", 10):
            raise ArenaError(409, "round limit reached: accept the standing offer or walk away")
        reply = self._public(t.respond(message))
        if t.closed and all(x.closed for x in self.threads.values()):
            self._end(None, "no_deal")
            return {**reply, "result": self.outcome}
        return reply

    def close(self, supplier_id, message):
        action = message.get("action") or {}
        if action.get("type") == "walk_away":
            self._end(None, "walked_away")
            return self.outcome
        if action.get("type") != "accept":
            raise ArenaError(422, "action is {'type': 'accept', 'term_sheet_id': ...} or 'walk_away'")
        sheet = action.get("term_sheet_id")
        owner = next(
            (s for s, t in self.threads.items() if not t.closed and t.standing and t.standing["term_sheet_id"] == sheet),
            None,
        )
        if owner is None:
            raise ArenaError(422, "not a standing offer in this session")
        self._end(owner, "accepted")
        return self.outcome

    def attachment(self, attachment_id):
        for t in self.threads.values():
            for m in t.messages:
                for a in m["attachments"]:
                    if a["attachment_id"] == attachment_id:
                        return a["text"].encode()
        raise ArenaError(404, "no such attachment in this session")

    def missed(self, supplier_id, error):
        if self.outcome is not None:
            return {"result": self.outcome}
        t = self.threads[supplier_id]
        last = self._public(t.messages[-1])
        return {**last, "body": f"({error.detail})", "status": "walked_away" if t.closed else t.status}

    def result(self):
        if self.outcome is None:
            self._end(None, "no_deal")
        return self.outcome

    # -- helpers -------------------------------------------------------------------------------
    def _thread(self, supplier_id):
        if self.outcome is not None:
            raise ArenaError(409, f"the session has ended: {self.outcome['end_reason']}")
        t = self.threads.get(supplier_id)
        if t is None:
            raise ArenaError(422, f"{supplier_id} is not a supplier in this case")
        if t.closed:
            raise ArenaError(409, f"the thread with {supplier_id} has ended: {t.closed}")
        return t

    def _check(self, terms):
        case = self.case
        if set(terms) != set(case["negotiable"]) or not (terms.get("unit_price") or 0) > 0:
            raise ArenaError(422, f"a term sheet carries exactly the negotiable fields {case['negotiable']}")
        for f, v in terms.items():
            options = case["term_options"].get(f)
            if f != "unit_price" and options and v not in options:
                raise ArenaError(422, f"{f}={v!r} is not one of {options}")

    @staticmethod
    def _public(msg):
        return copy.deepcopy(msg)

    def _end(self, owner, reason):
        sc, case = self.scenario, self.case
        c_alt = sc.c_alt
        r = {
            "ended": True,
            "end_reason": reason,
            "deal": False,
            "supplier_id": None,
            "offer_id": None,
            "terms": None,
            "c_open": sc.c_open,
            "c_deal": None,
            "c_alt": c_alt,
            "c_best": sc.c_best,
            "score": score(sc.c_open, c_alt, sc.c_best) if c_alt else 0.0,
            "must_haves_ok": None,
            "cost_breakdown": None,
            "rounds": sum(t.round for t in self.threads.values()),
        }
        if owner:
            t, p = self.threads[owner], sc.personas[owner]
            terms = closing_terms(case, t.standing["terms"], p.pdf_standard)
            breakdown = cost_breakdown(case, terms, p.pdf_standard, p.relationship_view())
            c_deal = round(sum(breakdown.values()), 2)
            ok = must_haves_ok(case, terms)
            r.update(
                deal=True,
                supplier_id=owner,
                offer_id=t.standing["term_sheet_id"],
                terms=terms,
                c_deal=c_deal,
                must_haves_ok=ok,
                cost_breakdown=breakdown,
                score=score(sc.c_open, c_deal, sc.c_best) if ok else 0.0,
            )
        r["trace"] = {sid: t.reasons for sid, t in self.threads.items()}
        for t in self.threads.values():
            t.closed = t.closed or reason
        self.outcome = r

